class Solution {
public:
    long long countPaths(int n, vector<vector<int>>& edges) {
        vector<bool> is_prime(n + 1, true);
        is_prime[0] = is_prime[1] = false;
        for (int p = 2; p * p <= n; p++) {
            if (is_prime[p]) {
                for (int i = p * p; i <= n; i += p) is_prime[i] = false;
            }
        }
        vector<vector<int>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<int> comp_id(n + 1, 0), comp_size(n + 1, 0);
        int cid = 1;
        for (int i = 1; i <= n; i++) {
            if (!is_prime[i] && comp_id[i] == 0) {
                vector<int> nodes = {i};
                comp_id[i] = cid;
                int head = 0;
                while (head < nodes.size()) {
                    int u = nodes[head++];
                    for (int v : adj[u]) {
                        if (!is_prime[v] && comp_id[v] == 0) {
                            comp_id[v] = cid;
                            nodes.push_back(v);
                        }
                    }
                }
                int sz = nodes.size();
                for (int u : nodes) comp_size[u] = sz;
                cid++;
            }
        }
        long long ans = 0;
        for (int p = 1; p <= n; p++) {
            if (is_prime[p]) {
                unordered_set<int> seen;
                vector<long long> sizes;
                for (int v : adj[p]) {
                    if (!is_prime[v]) {
                        int c = comp_id[v];
                        if (!seen.count(c)) {
                            seen.insert(c);
                            sizes.push_back(comp_size[v]);
                        }
                    }
                }
                long long pref = 0;
                for (long long s : sizes) {
                    ans += s;
                    ans += pref * s;
                    pref += s;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long countPaths(int n, int[][] edges) {
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int p = 2; p * p <= n; p++) {
            if (isPrime[p]) {
                for (int i = p * p; i <= n; i += p) isPrime[i] = false;
            }
        }
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] compId = new int[n + 1];
        int[] compSize = new int[n + 1];
        int cid = 1;
        for (int i = 1; i <= n; i++) {
            if (!isPrime[i] && compId[i] == 0) {
                List<Integer> nodes = new ArrayList<>();
                nodes.add(i);
                compId[i] = cid;
                int head = 0;
                while (head < nodes.size()) {
                    int u = nodes.get(head++);
                    for (int v : adj[u]) {
                        if (!isPrime[v] && compId[v] == 0) {
                            compId[v] = cid;
                            nodes.add(v);
                        }
                    }
                }
                int sz = nodes.size();
                for (int u : nodes) compSize[u] = sz;
                cid++;
            }
        }
        long ans = 0;
        for (int p = 1; p <= n; p++) {
            if (isPrime[p]) {
                Set<Integer> seen = new HashSet<>();
                List<Long> sizes = new ArrayList<>();
                for (int v : adj[p]) {
                    if (!isPrime[v]) {
                        int c = compId[v];
                        if (seen.add(c)) {
                            sizes.add((long) compSize[v]);
                        }
                    }
                }
                long pref = 0;
                for (long s : sizes) {
                    ans += s;
                    ans += pref * s;
                    pref += s;
                }
            }
        }
        return ans;
    }
}

